with with_gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 30 minutes then 1 else 0 end as is_new_session from device_readings), islands as (select *, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from with_gaps) select date_trunc('day', reading_ts) as activity_day, case when session_id >= 8 then 'LARGE' else 'SMALL' end as session_id_tier, count(*) filter (where device_code = 'DV-01') as dv_01_rows, max(reading_ts) as ended_at from islands group by 1, 2 having dv_01_rows >= 1 order by activity_day desc
